import React, { useState, useEffect } from 'react';
import Header from './components/Header';
import StatsPanel from './components/StatsPanel';
import FilterPanel from './components/FilterPanel';
import ResultsTable from './components/ResultsTable';
import { DomainEntry, DictionaryStats, FilterState, AnalysisResult } from './types';
import { parseDomains, applyFilters } from './utils/filterUtils';
import { 
  MOCK_PT_DICT, 
  MOCK_EN_DICT, 
  MOCK_CITIES, 
  MOCK_ANIMALS, 
  MOCK_NAMES,
  SAMPLE_DOMAINS_TXT 
} from './constants';
import { analyzeDomainsWithGemini } from './services/geminiService';
import { Language } from './constants/translations';

const INITIAL_FILTER_STATE: FilterState = {
  // Structure
  twoCharsWithNum: false,
  twoCharsNoNum: false,
  threeCharsWithNum: false,
  threeCharsNoNum: false,
  fourToFifteenPt: false,
  fourToFifteenEn: false,
  // Categories
  cities: false,
  animals: false,
  names: false,
  minerals: false,
  tech: false,
  // Extensions
  extComBr: false,
  extNetBr: false,
  extOrgBr: false,
  extBlogBr: false,
  extArtBr: false,
  extLojaBr: false,
  // Search
  keyword: ''
};

function App() {
  const [rawDomains, setRawDomains] = useState<DomainEntry[]>([]);
  const [filteredDomains, setFilteredDomains] = useState<DomainEntry[]>([]);
  const [filters, setFilters] = useState<FilterState>(INITIAL_FILTER_STATE);
  const [fileName, setFileName] = useState<string | null>(null);

  // UI States
  const [isDarkMode, setIsDarkMode] = useState(false);
  const [language, setLanguage] = useState<Language>('pt-BR');

  const [stats, setStats] = useState<DictionaryStats>({
    totalDomains: 0,
    portugueseWords: MOCK_PT_DICT.size,
    englishWords: MOCK_EN_DICT.size,
    cities: MOCK_CITIES.size,
    animals: MOCK_ANIMALS.size,
    names: MOCK_NAMES.size
  });

  // AI Analysis State
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [analysisResults, setAnalysisResults] = useState<AnalysisResult[]>([]);

  // Theme logic
  useEffect(() => {
    if (isDarkMode) {
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }
  }, [isDarkMode]);

  const toggleTheme = () => setIsDarkMode(!isDarkMode);

  const handleFileUpload = (content: string) => {
    const parsed = parseDomains(content);
    setRawDomains(parsed);
    setStats(prev => ({ ...prev, totalDomains: parsed.length }));
    setFileName("lista-personalizada.txt");
    setFilteredDomains([]); // Reset results
  };

  const loadSampleData = () => {
    const parsed = parseDomains(SAMPLE_DOMAINS_TXT);
    setRawDomains(parsed);
    setStats(prev => ({ ...prev, totalDomains: parsed.length }));
    setFileName("exemplo-sistema.txt");
  };

  const executeFilter = () => {
    const results = applyFilters(rawDomains, filters);
    setFilteredDomains(results);
    setAnalysisResults([]); // Reset AI results on new filter
  };

  const clearFilters = () => {
    setFilters(INITIAL_FILTER_STATE);
    setFilteredDomains([]);
    setAnalysisResults([]);
  };

  const handleGeminiAnalysis = async () => {
    if (filteredDomains.length === 0) return;

    setIsAnalyzing(true);
    try {
      const domainStrings = filteredDomains.map(d => d.name);
      const results = await analyzeDomainsWithGemini(domainStrings);
      setAnalysisResults(results);
    } catch (e) {
      console.error("Failed to analyze", e);
      alert("Erro ao conectar com Gemini API.");
    } finally {
      setIsAnalyzing(false);
    }
  };

  const currentDate = new Date().toLocaleString(language, { month: 'long', year: 'numeric' });
  const capitalizedDate = currentDate.charAt(0).toUpperCase() + currentDate.slice(1);

  return (
    <div className="min-h-screen bg-gray-100 dark:bg-gray-900 transition-colors duration-200 pb-20">
      <Header 
        currentDate={capitalizedDate} 
        isDarkMode={isDarkMode} 
        toggleTheme={toggleTheme}
        language={language}
        setLanguage={setLanguage}
      />

      <main className="max-w-4xl mx-auto px-4 -mt-4 relative z-10">
        <StatsPanel 
          stats={stats} 
          onFileUpload={handleFileUpload} 
          onLoadSample={loadSampleData}
          fileName={fileName}
          language={language}
        />

        <FilterPanel 
          filters={filters}
          setFilters={setFilters}
          onExecute={executeFilter}
          onClear={clearFilters}
          resultCount={filteredDomains.length}
          language={language}
        />

        <ResultsTable 
          domains={filteredDomains}
          onAnalyze={handleGeminiAnalysis}
          isAnalyzing={isAnalyzing}
          analysisResults={analysisResults}
          language={language}
        />
      </main>
    </div>
  );
}

export default App;

import { GoogleGenAI, Type } from "@google/genai";
import { AnalysisResult } from "../types";

export const analyzeDomainsWithGemini = async (domains: string[]): Promise<AnalysisResult[]> => {
  const apiKey = process.env.API_KEY;
  if (!apiKey) {
    throw new Error("API Key not found in environment variables.");
  }

  const ai = new GoogleGenAI({ apiKey });

  // Limit batch size to avoid token limits in this demo context
  const domainsToAnalyze = domains.slice(0, 30); 

  const prompt = `
    Analyze the following list of domains. For each domain, provide:
    1. A short analysis of its potential use (brandable, SEO, generic, etc.).
    2. A likely category (Tech, Commerce, Personal, etc.).
    3. A valuation rating (Low, Medium, High).

    List: ${domainsToAnalyze.join(', ')}
  `;

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              domain: { type: Type.STRING },
              analysis: { type: Type.STRING },
              category: { type: Type.STRING },
              valuation: { type: Type.STRING }
            },
            required: ["domain", "analysis", "category", "valuation"]
          }
        }
      }
    });

    if (response.text) {
      return JSON.parse(response.text) as AnalysisResult[];
    }
    return [];
  } catch (error) {
    console.error("Gemini Analysis Error:", error);
    throw error;
  }
};

import { DomainEntry, FilterState } from '../types';
import { 
  MOCK_PT_DICT, 
  MOCK_EN_DICT, 
  MOCK_CITIES, 
  MOCK_ANIMALS, 
  MOCK_NAMES,
  MOCK_SURNAMES,
  MOCK_MINERALS,
  MOCK_TECH
} from '../constants';

// Helper to remove extension for checking
const getSLD = (domain: string) => domain.split('.')[0];

export const parseDomains = (text: string): DomainEntry[] => {
  const lines = text.split(/\r?\n/);
  const domains: DomainEntry[] = [];

  for (const line of lines) {
    const cleanLine = line.trim().toLowerCase();
    if (!cleanLine || !cleanLine.includes('.')) continue;

    const parts = cleanLine.split('.');
    const name = parts[0];
    const extension = parts.slice(1).join('.');

    domains.push({
      name: cleanLine,
      length: name.length,
      hasNumbers: /\d/.test(name),
      hasHyphen: /-/.test(name),
      extension: extension
    });
  }
  return domains;
};

export const applyFilters = (domains: DomainEntry[], filters: FilterState): DomainEntry[] => {
  // Logic: 
  // 1. Keyword (AND) - if exists
  // 2. Extension (AND if any selected) - e.g. must be .com.br OR .net.br if those are checked
  // 3. Criteria (Structure OR Category) - if any criteria selected, domain must match at least one

  const isAnyCheckboxChecked = Object.values(filters).some(val => val === true);
  const hasKeyword = filters.keyword.trim().length > 0;

  // Basic check: if nothing selected, return all
  if (!isAnyCheckboxChecked && !hasKeyword) {
    return domains;
  }

  // Identify active filters groups
  const activeExtensions: string[] = [];
  if (filters.extComBr) activeExtensions.push('com.br');
  if (filters.extNetBr) activeExtensions.push('net.br');
  if (filters.extOrgBr) activeExtensions.push('org.br');
  if (filters.extBlogBr) activeExtensions.push('blog.br');
  if (filters.extArtBr) activeExtensions.push('art.br');
  if (filters.extLojaBr) activeExtensions.push('loja.br');

  const hasExtensionFilter = activeExtensions.length > 0;

  // Check if any "Structure" or "Category" filter is active
  const criteriaKeys: (keyof FilterState)[] = [
    'twoCharsWithNum', 'twoCharsNoNum', 'threeCharsWithNum', 'threeCharsNoNum',
    'fourToFifteenPt', 'fourToFifteenEn', 'cities', 'animals', 'names', 
    'minerals', 'tech'
  ];
  const hasCriteriaFilter = criteriaKeys.some(k => filters[k] === true);

  return domains.filter(d => {
    const sld = getSLD(d.name);

    // 1. Keyword Filter (Global Restriction)
    if (hasKeyword && !sld.includes(filters.keyword.toLowerCase())) {
      return false;
    }

    // 2. Extension Filter (Global Restriction)
    if (hasExtensionFilter) {
      if (!activeExtensions.includes(d.extension)) {
        return false;
      }
    }

    // 3. Criteria Filters (OR Logic within this group)
    // If no criteria filters are set, we pass (assuming matched keyword/extension is enough)
    if (!hasCriteriaFilter) {
      return true;
    }

    // If criteria filters ARE set, we must match at least one
    let criteriaMatch = false;

    // Structure
    if (filters.twoCharsWithNum && sld.length === 2 && d.hasNumbers) criteriaMatch = true;
    if (filters.twoCharsNoNum && sld.length === 2 && !d.hasNumbers) criteriaMatch = true;
    if (filters.threeCharsWithNum && sld.length === 3 && d.hasNumbers) criteriaMatch = true;
    if (filters.threeCharsNoNum && sld.length === 3 && !d.hasNumbers) criteriaMatch = true;

    // Dictionary
    if (sld.length >= 4 && sld.length <= 15) {
      if (filters.fourToFifteenPt && MOCK_PT_DICT.has(sld)) criteriaMatch = true;
      if (filters.fourToFifteenEn && MOCK_EN_DICT.has(sld)) criteriaMatch = true;
    }

    // Categories
    if (filters.cities && MOCK_CITIES.has(sld)) criteriaMatch = true;
    if (filters.animals && MOCK_ANIMALS.has(sld)) criteriaMatch = true;
    if (filters.names && (MOCK_NAMES.has(sld) || MOCK_SURNAMES.has(sld))) criteriaMatch = true;
    if (filters.minerals && MOCK_MINERALS.has(sld)) criteriaMatch = true;
    if (filters.tech && MOCK_TECH.has(sld)) criteriaMatch = true;

    return criteriaMatch;
  });
};

